<?php

namespace Database\Factories;

use App\Enums\ReportCategoryEnum;
use App\Enums\ReportStatusEnum;
use App\Models\Report;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Report>
 */
class ReportFactory extends Factory
{
    protected $model = Report::class;

    /**
     * The tracking token is generated by Report::booted().
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'category' => fake()->randomElement(ReportCategoryEnum::cases()),
            'status' => ReportStatusEnum::SUBMITTED,
            'subject' => fake()->sentence(6),
            'body' => fake()->paragraphs(3, true),
            'incident_date' => fake()->date(),
            'incident_location' => fake()->city(),
            'organisation_involved' => fake()->company(),
            'priority' => 2,
        ];
    }

    // ── States ────────────────────────────────────────────────────────────

    public function withStatus(ReportStatusEnum $status): static
    {
        return $this->state(fn () => ['status' => $status]);
    }

    public function assignedTo(User $user): static
    {
        return $this->state(fn () => ['assigned_to' => $user->id]);
    }

    public function highPriority(): static
    {
        return $this->state(fn () => ['priority' => 3]);
    }
}
